import{_ as a,c as s,o as n,ag as r}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Researching for a TAAW","description":"","frontmatter":{"title":"Researching for a TAAW"},"headers":[],"relativePath":"research/researching-for-a-taaw.md","filePath":"research/researching-for-a-taaw.md","lastUpdated":null}'),i={name:"research/researching-for-a-taaw.md"};function t(o,e,l,p,h,c){return n(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="researching-for-a-taaw" tabindex="-1">Researching for a TAAW <a class="header-anchor" href="#researching-for-a-taaw" aria-label="Permalink to &quot;Researching for a TAAW&quot;">​</a></h1><h2 id="taaw-research-workflow" tabindex="-1">TAAW Research Workflow <a class="header-anchor" href="#taaw-research-workflow" aria-label="Permalink to &quot;TAAW Research Workflow&quot;">​</a></h2><p>The Deployed PSYOP team should contact the OPCEN for research support BEFORE the TAAW is written, as access to Secret information is difficult for deployed teams. Using Enclosure 1, OPCEN can perform general research to help the Deployed team decide on the direction they wish to take. Once a decision has been made, the OPCEN can provide further research in that specified direction.</p><p>The deployed PSYOP team should contact available INTEL and PAI support for TAAW support or request OPCEN to do this at least a month in advance.</p><h3 id="research-workflow" tabindex="-1">Research Workflow <a class="header-anchor" href="#research-workflow" aria-label="Permalink to &quot;Research Workflow&quot;">​</a></h3><p><strong>See TM 3-53.11 Influence Process Activity: Target Audience Analysis (TAA) for more.</strong></p><p>Search high to low and cycle anytime you hit a dead end for too long. Keep at least the link to the report or maintain citations during research to avoid going back and researching again when you figure out what goes into the final document.</p><ol><li><p><strong>Search and define the supporting behaviors required to complete the Desired Behavior.</strong> (e.g. To vote, you must go to the polling place, be registered to vote, have ID, and meet the eligibility requirements.)</p></li><li><p><strong>Research the Desired Behavior and supporting behaviors in the area of interest.</strong> Historically, what does that look like? Who does it, when, where, and why? You may find out whether your TA is involved already or not. Why or why not?</p><ul><li>Identify entities of interest associated with the behavior.</li><li>Identify locations associated with the behavior (NAIs?).</li><li>Identify times associated with the behavior (holidays, schedules, peak times, etc.).</li><li>Identify reactions to that behavior (e.g., protests typically lead the government to do xyz while certain groups do abc).</li><li>What symbols are used for the Desired Behavior and supporting behaviors? <ul><li>Symbols supporting.</li><li>Symbols opposing.</li></ul></li><li>Who is publicly talking about the Desired Behavior and supporting behaviors? <ul><li>Encouraging or supporting the Desired Behavior and supporting behaviors.</li><li>Discouraging or opposing the Desired Behavior and supporting behaviors.</li></ul></li><li>What are the biggest hurdles or challenges to the Desired Behavior and supporting behaviors?</li></ul></li></ol><h2 id="impact-of-the-desired-behavior-and-supporting-behaviors" tabindex="-1">Impact of the Desired Behavior and Supporting Behaviors <a class="header-anchor" href="#impact-of-the-desired-behavior-and-supporting-behaviors" aria-label="Permalink to &quot;Impact of the Desired Behavior and Supporting Behaviors&quot;">​</a></h2><ul><li><strong>Actual impact.</strong></li><li><strong>Perceived impact.</strong></li><li><strong>Who is impacted the most?</strong><ul><li>TA&#39;s relation to those impacted.</li></ul></li></ul><h2 id="obtain-refined-ta-based-on-research" tabindex="-1">Obtain Refined TA Based on Research <a class="header-anchor" href="#obtain-refined-ta-based-on-research" aria-label="Permalink to &quot;Obtain Refined TA Based on Research&quot;">​</a></h2><p>Based on research on the desired behavior in the area of interest:</p><ul><li>Search for historical data showing the refined TA participating in the desired or supporting behavior.</li><li>Search for historical data showing the refined TA is NOT ABLE TO participate in the desired or supporting behavior.</li><li>Map out TA&#39;s relation to where the behavior must occur (home, school, work, online, etc.).</li><li>Search for synonyms or how the TA is typically referred to (online, on government reports, etc.).</li></ul><h2 id="current-behavior-and-the-refined-ta" tabindex="-1">Current Behavior and the Refined TA <a class="header-anchor" href="#current-behavior-and-the-refined-ta" aria-label="Permalink to &quot;Current Behavior and the Refined TA&quot;">​</a></h2><ul><li>Search for instances of the TA at or near the area of interest for the Behavior or supporting behaviors.</li><li>Assess which intermediate behavior the TA is doing, doing most, not doing, and avoiding.</li></ul><h2 id="starting-point-for-research-high-to-low" tabindex="-1">Starting Point For Research (High to Low) <a class="header-anchor" href="#starting-point-for-research-high-to-low" aria-label="Permalink to &quot;Starting Point For Research (High to Low)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classification</th><th>Resource</th></tr></thead><tbody><tr><td>TS</td><td>Intellipedia Intel Links and Library</td></tr><tr><td>SIPR</td><td>Intellipedia Intel Links and Library</td></tr><tr><td>NIPR</td><td>See applicable resources</td></tr><tr><td>Open Source</td><td><a href="/research/">Research Resources</a></td></tr></tbody></table><h2 id="formatting-the-research-document" tabindex="-1">Formatting the Research Document <a class="header-anchor" href="#formatting-the-research-document" aria-label="Permalink to &quot;Formatting the Research Document&quot;">​</a></h2><ol><li><p>Create a separate research Word document to accompany TAAW.</p><ul><li>Name file: <em>Series_Name-Enc2-Research</em></li></ul></li><li><p>Copy header data from TAAW over to the research document to include PO, SMO, desired behavior, and refined target audience.</p></li><li><p>The first paragraph should be a &quot;PSYOP so what&quot; highlighted in green to differentiate from actual sources and summarize the entirety of the research findings.</p></li><li><p>Follow PSYOP so what with a line break of forward slashes.</p><ul><li>Do this after each source and header data.</li></ul></li><li><p>Each intel source should be listed in the following order:</p><ul><li>Citation</li><li>PSYOP so what highlighted in green</li><li>Information with portion marking</li></ul></li></ol><h3 id="example-format" tabindex="-1">Example Format <a class="header-anchor" href="#example-format" aria-label="Permalink to &quot;Example Format&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(APPROPRIATE CLASSIFICATION) PO: #######################</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) SPO: ######################</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) Desired behavior: ###########</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) Refined TA: ###############</span></span>
<span class="line"><span></span></span>
<span class="line"><span>///////////////////////////////////////</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) overarching PSYOP SO WHAT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>////////////////////////////////////////</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Citation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) source 1 PSYOP SO WHAT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) source information</span></span>
<span class="line"><span></span></span>
<span class="line"><span>////////////////////////////////////////</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Citation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) source 2 PSYOP SO WHAT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(APPROPRIATE CLASSIFICATION) source information</span></span>
<span class="line"><span></span></span>
<span class="line"><span>////////////////////////////////////////</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br></div></div><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/research/">Research Overview</a></li><li><a href="/research/research-preparation.html">Research Preparation</a></li><li><a href="/research/research-tools.html">Research Tools</a></li><li><a href="/research/research-datasets.html">Research Datasets</a></li></ul>`,23)])])}const b=a(i,[["render",t]]);export{u as __pageData,b as default};
